@startuml

class User {
  + openNewDocument()
  + openExistingDocument()
  + saveDocument()
  + printDocument()
}

class Document {}

class Page {
  + pageNumber : int
  + date : date
  + time : time
}

class Header {
  + date : date
  + time : time
  + pageNumber : int
}

class Footer {
  + date : date
  + time : time
  + pageNumber : int
}

class Body {}

class Sentence {}

class Word {
  + content : string
}

class PunctuationCharacter {}

class Picture {}

class Table {}

class Row {}

class Column {}

class Cell {}

Document "1" *-- "1..*" Page
Page "1" *-- "1" Header
Page "1" *-- "1" Body
Page "1" *-- "1" Footer
Body "1" *-- "*" Sentence
Body "1" *-- "*" Picture
Body "1" *-- "*" Table
Sentence "1" *-- "*" Word
Sentence "1" *-- "*" PunctuationCharacter
Table "1" *-- "1..*" Row
Table "1" *-- "1..*" Column
Row "1" *-- "*" Cell
Column "1" *-- "*" Cell
Cell "1" *-- "0..*" Word
Cell "1" *-- "0..*" Picture

User "1" -- "*" Document : manages

@enduml

